// Dados fictícios usados apenas para validar o Motor de Performance.
// Nada deste node é gravado na Meta ou no Google Sheets.
const data = '2026-08-12';
const conta = 'CONTA_TESTE';

const base = [
  { id: 'ANUNCIO_A', investimento: 50, impressoes: 5000, alcance: 3000, cliques: 100, cliquesLink: 80, conversas: 10 },
  { id: 'ANUNCIO_B', investimento: 70, impressoes: 6000, alcance: 3500, cliques: 90, cliquesLink: 65, conversas: 5 },
  { id: 'ANUNCIO_C', investimento: 30, impressoes: 3000, alcance: 2200, cliques: 50, cliquesLink: 40, conversas: 0 }
];

return base.map(x => ({
  json: {
    'CHAVE REGISTRO': `${data}|${conta}|anuncio|${x.id}`,
    'DATA REFERENCIA': data,
    'CONTA ANUNCIO': conta,
    'NIVEL ANALISE': 'Anúncio',
    'ID CAMPANHA': 'CAMPANHA_TESTE',
    'NOME CAMPANHA': 'Campanha de Teste',
    'OBJETIVO': 'Conversões',
    'OBJETIVO ORIGINAL': 'CONVERSIONS',
    'ID CONJUNTO': 'CONJUNTO_TESTE',
    'NOME CONJUNTO': 'Conjunto de Teste',
    'ID ANUNCIO': x.id,
    'NOME ANUNCIO': x.id,
    'INVESTIMENTO': x.investimento,
    'IMPRESSOES': x.impressoes,
    'ALCANCE': x.alcance,
    'CLIQUES': x.cliques,
    'CLIQUES LINK': x.cliquesLink,
    'CONVERSAS INICIADAS': x.conversas,
    'ORIGEM DADOS': 'TESTE'
  }
}));

// Usa somente registros da nova base diária (Fase 1).
function numero(v) {
  if (v === undefined || v === null || v === '') return 0;
  if (typeof v === 'number') return v;

  let texto = String(v).replace(/\s/g, '').replace('R$', '');

  if (texto.includes(',') && texto.includes('.')) {
    texto = texto.replace(/\./g, '').replace(',', '.');
  } else if (texto.includes(',')) {
    texto = texto.replace(',', '.');
  }

  return Number(texto) || 0;
}

function dividir(a, b) {
  return b > 0 ? a / b : null;
}

function percentual(a, b) {
  const valor = dividir(a, b);
  return valor === null ? null : valor * 100;
}

function arredondar(valor) {
  return valor === null || valor === undefined
    ? null
    : Number(valor.toFixed(4));
}

function campo(objeto, ...chaves) {
  for (const chave of chaves) {
    if (objeto[chave] !== undefined && objeto[chave] !== null && objeto[chave] !== '') {
      return objeto[chave];
    }
  }
  return '';
}

const base = items
  .map(item => {
    const limpo = {};
    for (const [chave, valor] of Object.entries(item.json || {})) {
      limpo[String(chave).trim()] = valor;
    }
    return limpo;
  })
  .filter(item => String(item['CHAVE REGISTRO'] || '').trim());

if (!base.length) {
  return [{
    json: {
      status_motor: 'SEM_DADOS_DIARIOS',
      mensagem: 'Nenhum registro diário com CHAVE REGISTRO foi encontrado.'
    }
  }];
}

const dados = base.map(item => {
  const investimento = numero(item.INVESTIMENTO);
  const impressoes = numero(item.IMPRESSOES);
  const alcance = numero(item.ALCANCE);
  const cliques = numero(item.CLIQUES);
  const cliquesLink = numero(campo(item, 'CLIQUES LINK', 'CLIQUES LINK '));
  const conversas = numero(item['CONVERSAS INICIADAS']);

  return {
    original: item,
    data: String(item['DATA REFERENCIA'] || item['DATA INCIO'] || ''),
    conta: String(item['CONTA ANUNCIO'] || ''),
    nivel: String(campo(item, 'NIVEL ANALISE', 'NÍVEL ANÁLISE')),
    objetivo: String(item['OBJETIVO ORIGINAL'] || item.OBJETIVO || ''),
    investimento, impressoes, alcance, cliques, cliquesLink, conversas,
    ctr: percentual(cliques, impressoes),
    ctrLink: percentual(cliquesLink, impressoes),
    cpc: dividir(investimento, cliques),
    cpm: impressoes > 0 ? investimento / impressoes * 1000 : null,
    custoConversa: dividir(investimento, conversas),
    taxaCliqueConversa: percentual(conversas, cliquesLink),
    frequencia: dividir(impressoes, alcance)
  };
});

const grupos = new Map();

for (const item of dados) {
  const chave = [item.data, item.conta, item.nivel, item.objetivo].join('|');

  if (!grupos.has(chave)) {
    grupos.set(chave, {
      quantidade: 0, investimento: 0, impressoes: 0, alcance: 0,
      cliques: 0, cliquesLink: 0, conversas: 0
    });
  }

  const grupo = grupos.get(chave);
  grupo.quantidade++;
  grupo.investimento += item.investimento;
  grupo.impressoes += item.impressoes;
  grupo.alcance += item.alcance;
  grupo.cliques += item.cliques;
  grupo.cliquesLink += item.cliquesLink;
  grupo.conversas += item.conversas;
}

function benchmark(item) {
  const chave = [item.data, item.conta, item.nivel, item.objetivo].join('|');
  const grupo = grupos.get(chave);

  return {
    quantidade: grupo.quantidade,
    investimento: dividir(grupo.investimento, grupo.quantidade),
    ctrLink: percentual(grupo.cliquesLink, grupo.impressoes),
    cpc: dividir(grupo.investimento, grupo.cliques),
    cpm: grupo.impressoes > 0 ? grupo.investimento / grupo.impressoes * 1000 : null,
    custoConversa: dividir(grupo.investimento, grupo.conversas),
    taxaCliqueConversa: percentual(grupo.conversas, grupo.cliquesLink),
    frequencia: dividir(grupo.impressoes, grupo.alcance)
  };
}

function calcularScore(item, media) {
  let score = 50;

  if (item.conversas > 0 && item.custoConversa && media.custoConversa) {
    const indice = media.custoConversa / item.custoConversa;
    if (indice >= 1.3) score += 20;
    else if (indice >= 1.1) score += 12;
    else if (indice <= 0.7) score -= 20;
    else if (indice <= 0.9) score -= 12;
  } else if (
    item.investimento > 0 && item.conversas === 0 &&
    media.custoConversa && item.investimento >= media.custoConversa
  ) {
    score -= 20;
  }

  if (item.ctrLink !== null && media.ctrLink) {
    const indice = item.ctrLink / media.ctrLink;
    if (indice >= 1.3) score += 10;
    else if (indice >= 1.1) score += 5;
    else if (indice <= 0.7) score -= 10;
    else if (indice <= 0.9) score -= 5;
  }

  if (item.cpc && media.cpc) {
    const indice = media.cpc / item.cpc;
    if (indice >= 1.3) score += 10;
    else if (indice >= 1.1) score += 5;
    else if (indice <= 0.7) score -= 10;
    else if (indice <= 0.9) score -= 5;
  }

  if (item.taxaCliqueConversa !== null && media.taxaCliqueConversa) {
    const indice = item.taxaCliqueConversa / media.taxaCliqueConversa;
    if (indice >= 1.3) score += 10;
    else if (indice >= 1.1) score += 5;
    else if (indice <= 0.7) score -= 10;
    else if (indice <= 0.9) score -= 5;
  }

  return Math.max(0, Math.min(100, score));
}

return dados.map(item => {
  const media = benchmark(item);
  return {
    json: {
      ...item.original,
      'CTR CALCULADO': arredondar(item.ctr),
      'CTR LINK': arredondar(item.ctrLink),
      'CPC CALCULADO': arredondar(item.cpc),
      'CPM CALCULADO': arredondar(item.cpm),
      'CUSTO CONVERSA CALCULADO': arredondar(item.custoConversa),
      'TAXA CLIQUE CONVERSA': arredondar(item.taxaCliqueConversa),
      'FREQUENCIA': arredondar(item.frequencia),
      'MEDIA INVESTIMENTO OBJETO': arredondar(media.investimento),
      'MEDIA CTR LINK': arredondar(media.ctrLink),
      'MEDIA CPC': arredondar(media.cpc),
      'MEDIA CPM': arredondar(media.cpm),
      'MEDIA CUSTO CONVERSA': arredondar(media.custoConversa),
      'MEDIA TAXA CLIQUE CONVERSA': arredondar(media.taxaCliqueConversa),
      'MEDIA FREQUENCIA': arredondar(media.frequencia),
      'INDICE GASTO VS MEDIA': arredondar(dividir(item.investimento, media.investimento)),
      'SCORE TECNICO': calcularScore(item, media),
      'QUANTIDADE OBJETOS BENCHMARK': media.quantidade
    }
  };
});

// Gera uma saída compacta para os próximos fluxos.
if (items.length === 1 && items[0].json.status_motor === 'SEM_DADOS_DIARIOS') {
  return items;
}

function numero(v) {
  if (v === undefined || v === null || v === '') return 0;
  if (typeof v === 'number') return v;
  let texto = String(v).replace(/\s/g, '').replace('R$', '');
  if (texto.includes(',') && texto.includes('.')) texto = texto.replace(/\./g, '').replace(',', '.');
  else if (texto.includes(',')) texto = texto.replace(',', '.');
  return Number(texto) || 0;
}

const registros = items.map(item => item.json);
const investimentoTotal = registros.reduce((soma, item) => soma + numero(item.INVESTIMENTO), 0);
const conversas = registros.reduce((soma, item) => soma + numero(item['CONVERSAS INICIADAS']), 0);
const ordenados = [...registros].sort((a, b) => numero(b['SCORE TECNICO']) - numero(a['SCORE TECNICO']));

function nome(item) {
  return item['NOME ANUNCIO'] || item.ANUNCIO || item['NOME CONJUNTO'] || item.CONJUNTO || item['NOME CAMPANHA'] || 'Sem nome';
}

function resumoObjeto(item) {
  return {
    nivel: item['NIVEL ANALISE'] || item['NÍVEL ANÁLISE'] || '',
    nome: nome(item),
    score: numero(item['SCORE TECNICO']),
    investimento: numero(item.INVESTIMENTO),
    conversas: numero(item['CONVERSAS INICIADAS']),
    custo_conversa: item['CUSTO CONVERSA CALCULADO'],
    ctr_link: item['CTR LINK'],
    cpc: item['CPC CALCULADO']
  };
}

return [{
  json: {
    status_motor: 'OK',
    data_referencia: registros[0]['DATA REFERENCIA'] || registros[0]['DATA INCIO'] || '',
    quantidade_registros: registros.length,
    investimento_total: Number(investimentoTotal.toFixed(2)),
    conversas_iniciadas: conversas,
    custo_medio_por_conversa: conversas > 0 ? Number((investimentoTotal / conversas).toFixed(2)) : null,
    score_tecnico_medio: Number((registros.reduce((soma, item) => soma + numero(item['SCORE TECNICO']), 0) / registros.length).toFixed(2)),
    melhores_resultados: ordenados.slice(0, 5).map(resumoObjeto),
    resultados_para_atencao: ordenados.slice(-5).reverse().map(resumoObjeto),
    registros_performance: registros
  }
}];
